package com.aistock.gateway.statistics;
import com.aistock.common.*;import com.aistock.gateway.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.*;import org.springframework.http.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AdminStatisticsProxyTest {
 UserPublicClient user;MarketPublicClient market;ForecastPublicClient prediction;SchedulerPublicClient scheduler;StatisticsIdentityClient identity;MockMvc mvc;
 final String base="/api/v1/admin/statistics/";final Cookie cookie=new Cookie("AISTOCK_SESSION","admin");
 @BeforeEach void init(){user=mock(UserPublicClient.class);market=mock(MarketPublicClient.class);prediction=mock(ForecastPublicClient.class);scheduler=mock(SchedulerPublicClient.class);identity=mock(StatisticsIdentityClient.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"ADMIN",1),"test"));var reply=ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body("{\"code\":\"OK\",\"data\":{}}".getBytes(java.nio.charset.StandardCharsets.UTF_8));when(user.get(anyString(),anyMap(),anyMap())).thenReturn(reply);when(market.get(anyString(),anyMap(),anyMap())).thenReturn(reply);when(prediction.get(anyString(),anyMap(),anyMap())).thenReturn(reply);when(scheduler.get(anyString(),any(),anyMap())).thenReturn(reply);var clock=Clock.fixed(Instant.parse("2026-10-22T04:00:00Z"),ZoneOffset.UTC);mvc=MockMvcBuilders.standaloneSetup(new AdminStatisticsApiProxyController(user,market,prediction,scheduler,new StatisticsAdminAccess(identity,"server-test"),new HttpStatisticsCollector(clock.instant(),clock),new ObjectMapper().findAndRegisterModules(),clock),new UserApiProxyController(user,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).addFilters(StatisticsCorsFixture.filter()).build();}
 @Test void exactSectionsPreserveDatesAndMarketPaginationWithoutForgedIdentity()throws Exception{for(var name:List.of("users","predictions","tasks","market")){var q=get(base+name).cookie(cookie).param("from","2026-10-20").param("to","2026-10-22").header("X-Role","ADMIN");if(name.equals("market"))q.param("page","2").param("size","10");mvc.perform(q).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}verify(user).get(eq("admin/statistics/users"),eq(Map.of("from","2026-10-20","to","2026-10-22")),argThat(x->!x.containsKey("X-Role")));verify(market).get(eq("admin/statistics/market"),eq(Map.of("from","2026-10-20","to","2026-10-22","page","2","size","10")),anyMap());verify(prediction).get(eq("admin/statistics/predictions"),anyMap(),anyMap());verify(scheduler).get(eq("admin/statistics/tasks"),any(),anyMap());}
 @Test void invalidParametersAndMethodsNeverCallBusinessServices()throws Exception{mvc.perform(get(base+"http").cookie(cookie).param("from","2026-10-20")).andExpect(status().isBadRequest());mvc.perform(get(base+"users").cookie(cookie).param("from","2026-10-20","2026-10-20").param("to","2026-10-22")).andExpect(status().isBadRequest());mvc.perform(post(base+"users").cookie(cookie)).andExpect(status().isNotFound());mvc.perform(get(base+"unknown").cookie(cookie)).andExpect(status().isNotFound());verifyNoInteractions(user,market,prediction,scheduler);}
 @Test void inaccessibleOrMalformedServiceIsNotReportedAsZeroOrAccountFailure()throws Exception{when(market.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.status(503).body("SQL private-secret".getBytes()));mvc.perform(get(base+"market").cookie(cookie)).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("STATISTICS_UNAVAILABLE")).andExpect(jsonPath("$.data").isEmpty()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-secret"))));}
 @Test void httpStatisticsUsesAuthoritativeRoleAndRejectsAmbiguousCookies()throws Exception{mvc.perform(get(base+"http")).andExpect(status().isUnauthorized());mvc.perform(get(base+"http").cookie(cookie,cookie)).andExpect(status().isUnauthorized());when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"USER",1),"test"));mvc.perform(get(base+"http").cookie(cookie).header("X-Role","ADMIN")).andExpect(status().isForbidden());when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"ADMIN",1),"test"));mvc.perform(get(base+"http").cookie(cookie)).andExpect(status().isOk()).andExpect(jsonPath("$.data.scope").value("CURRENT_GATEWAY_PROCESS"));}
 @Test void oversizedResponseIsRejected()throws Exception{when(market.get(anyString(),anyMap(),anyMap())).thenReturn(ResponseEntity.ok(new byte[262145]));mvc.perform(get(base+"market").cookie(cookie)).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("STATISTICS_UNAVAILABLE"));}
 @Test void identityInfrastructureFailureCannotLeakBusinessDetails()throws Exception{when(identity.resolve(any(),anyString())).thenThrow(new BusinessException("PRIVATE_SQL_DETAIL","private-secret",HttpStatus.INTERNAL_SERVER_ERROR));mvc.perform(get(base+"http").cookie(cookie)).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("USER_SERVICE_UNAVAILABLE")).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-secret"))));}
 @Test void preflightDoesNotResolveIdentityOrQueryServices()throws Exception{mvc.perform(options(base+"users").header("Origin","http://127.0.0.1:15173").header("Access-Control-Request-Method","GET")).andExpect(status().isOk());mvc.perform(options(base+"users").header("Origin","https://outside.invalid").header("Access-Control-Request-Method","GET")).andExpect(status().isForbidden());verifyNoInteractions(identity,user,market,prediction,scheduler);}
}
